// Synthetic media for the media pipeline acceptance run: clips generated by FFmpeg (never a real reporter file),
// the payloads a hostile upload would use, and the frame-timestamp arithmetic behind the proxy-accuracy measurement.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { createReadStream } from "node:fs";

const FFMPEG = process.env.FFMPEG_BIN ?? "ffmpeg";
const FFPROBE = process.env.FFPROBE_BIN ?? "ffprobe";

/** Revealing values planted in the clip's container tags (iPhone style). None of them may surface anywhere downstream. */
export const LEAK = {
  "com.apple.quicktime.location.ISO6709": "+31.7767+035.2345+000.000/",
  "com.apple.quicktime.make": "AcceptanceMaker",
  "com.apple.quicktime.model": "iPhone15,2",
};
export const LEAK_VALUES = Object.values(LEAK);

const run = (bin, args, opts = {}) => execFileSync(bin, args, { stdio: ["ignore", "pipe", "pipe"], maxBuffer: 64 * 1024 * 1024, ...opts });

/**
 * One synthetic clip: test pattern + 440 Hz tone. `vfr` drops one frame in seven, `gap` removes a stretch of
 * frames, `startOffset` shifts the first timestamp (what phones record), `tags` plants the revealing container tags.
 */
export function synthClip(path, { seconds = 10, size = "1280x720", rate = 30, vfr = false, gap = null, startOffset = 0, tags = true, noise = false } = {}) {
  // `noise` swaps the test pattern for random pixels at a fixed high bitrate: a valid clip of a predictable, large size
  const source = noise ? `nullsrc=size=${size}:rate=${rate}:duration=${seconds},geq=random(1)*255:128:128` : `testsrc2=size=${size}:rate=${rate}:duration=${seconds}`;
  const args = ["-hide_banner", "-nostdin", "-loglevel", "error", "-y",
    "-f", "lavfi", "-i", source,
    "-f", "lavfi", "-i", `sine=frequency=440:sample_rate=48000:duration=${seconds}`];
  const conds = [];
  if (vfr) conds.push("not(eq(mod(n,7),3))");
  if (gap) conds.push(`not(between(t,${gap[0]},${gap[1]}))`);
  if (conds.length) args.push("-vf", `select='${conds.join("*")}'`, "-fps_mode", "vfr");
  args.push("-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", ...(noise ? ["-b:v", "8M", "-minrate", "8M", "-maxrate", "8M", "-bufsize", "4M"] : []), "-c:a", "aac");
  if (startOffset) args.push("-output_ts_offset", String(startOffset));
  if (tags) {
    args.push("-movflags", "use_metadata_tags");
    for (const [k, v] of Object.entries(LEAK)) args.push("-metadata", `${k}=${v}`);
  }
  args.push(path);
  run(FFMPEG, args);
  return path;
}

/** Remuxes `src` into `dst` with a display-rotation side data of `degrees` (what a phone held upright writes), streams copied. */
export function rotateClip(src, dst, degrees) {
  run(FFMPEG, ["-hide_banner", "-nostdin", "-loglevel", "error", "-y", "-display_rotation", String(degrees), "-copyts", "-i", src, "-c", "copy", "-movflags", "use_metadata_tags", dst]);
  return dst;
}

/**
 * An HDR clip as phones record it: HEVC 10-bit, BT.2020, HLG (`arib-std-b67`) or PQ (`smpte2084`), with the same planted
 * revealing tags as `synthClip`. Needs an FFmpeg with libx265.
 */
export function synthHdrClip(path, { seconds = 6, size = "1280x720", rate = 30, transfer = "arib-std-b67" } = {}) {
  const args = ["-hide_banner", "-nostdin", "-loglevel", "error", "-y",
    "-f", "lavfi", "-i", `testsrc2=size=${size}:rate=${rate}:duration=${seconds}`,
    "-f", "lavfi", "-i", `sine=frequency=440:sample_rate=48000:duration=${seconds}`,
    "-c:v", "libx265", "-preset", "ultrafast", "-pix_fmt", "yuv420p10le", "-tag:v", "hvc1",
    "-x265-params", `log-level=error:colorprim=bt2020:transfer=${transfer}:colormatrix=bt2020nc`,
    "-color_primaries", "bt2020", "-color_trc", transfer, "-colorspace", "bt2020nc", "-c:a", "aac", "-movflags", "use_metadata_tags"];
  for (const [k, v] of Object.entries(LEAK)) args.push("-metadata", `${k}=${v}`);
  args.push(path);
  run(FFMPEG, args);
  return path;
}

/** A string planted inside the H.264 bitstream itself (an SEI user_data_unregistered message), which stream copy keeps. */
export const SEI_VALUE = "AcceptanceSeiDevice-9f3a";
const SEI_UUID = "0123456789abcdef0123456789abcdef";

/** Remuxes `src` (H.264) into `dst` with `SEI_VALUE` inserted into every access unit's SEI, streams otherwise copied. */
export function plantSei(src, dst) {
  run(FFMPEG, ["-hide_banner", "-nostdin", "-loglevel", "error", "-y", "-copyts", "-i", src, "-c", "copy",
    "-bsf:v", `h264_metadata=sei_user_data=${SEI_UUID}+${SEI_VALUE}`, "-movflags", "use_metadata_tags", dst]);
  return dst;
}

/** Spoken Arabic from espeak-ng (a synthetic voice: no recording of anyone). Throws when espeak-ng is not installed. */
export function espeakArabic(wavPath, text) {
  run("espeak-ng", ["-v", "ar", "-s", "150", "-w", wavPath, text]);
  return wavPath;
}

/** A phone-style clip: test pattern video + the given speech looped to `seconds`, AAC audio. No revealing tags. */
export function synthSpeechClip(path, { speech, seconds = 45, size = "1280x720", rate = 30 }) {
  run(FFMPEG, ["-hide_banner", "-nostdin", "-loglevel", "error", "-y",
    "-f", "lavfi", "-i", `testsrc2=size=${size}:rate=${rate}:duration=${seconds}`,
    "-stream_loop", "-1", "-i", speech, "-t", String(seconds),
    "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", "-c:a", "aac", "-ar", "48000", path]);
  return path;
}

/** Presentation times (seconds, ascending) of every video packet. */
export function videoTimes(path) {
  const out = run(FFPROBE, ["-v", "error", "-select_streams", "v:0", "-show_entries", "packet=pts_time", "-of", "csv=p=0", path]).toString();
  return out.split(/\s+/).map((x) => Number(x.replace(/,$/, ""))).filter((x) => Number.isFinite(x)).sort((a, b) => a - b);
}

/** Everything ffprobe reports as container or stream tags, as one string (to look for planted values). */
export function tagDump(path) {
  return run(FFPROBE, ["-v", "error", "-show_entries", "format_tags:stream_tags", "-of", "json", path]).toString();
}

export function durationSeconds(path) {
  return Number(run(FFPROBE, ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", path]).toString().trim());
}

/** Width and height of the first video/image stream (a JPEG is one), or null when ffprobe cannot read it. */
export function imageSize(path) {
  try {
    const [w, h] = run(FFPROBE, ["-v", "error", "-select_streams", "v:0", "-show_entries", "stream=width,height", "-of", "csv=p=0:s=x", path]).toString().trim().split("x").map(Number);
    return w > 0 && h > 0 ? { width: w, height: h } : null;
  } catch { return null; }
}

export function sha256File(path) {
  return new Promise((resolve, reject) => {
    const h = createHash("sha256");
    createReadStream(path).on("data", (c) => h.update(c)).on("end", () => resolve(h.digest("hex"))).on("error", reject);
  });
}

function nearest(sorted, t) {
  let lo = 0, hi = sorted.length - 1;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (sorted[mid] < t) lo = mid + 1; else hi = mid;
  }
  const a = sorted[Math.max(lo - 1, 0)], b = sorted[lo];
  return Math.abs(a - t) <= Math.abs(b - t) ? a : b;
}

const mulberry32 = (seed) => () => {
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};

/**
 * Cut-back accuracy: at `points` pseudo-random frames of the original, where the editor would cut, the same frame on
 * the proxy must carry the same timestamp within the tolerance. Frames are matched by position when both streams have
 * the same frame count (the proxy keeps every frame): matching by nearest time instead would call a proxy shifted by
 * whole frames "accurate". With different counts it falls back to the nearest frame, and says so (`byIndex: false`).
 * Returns the worst gap in ms, the frame counts and the points used.
 */
export function cutBack(originalTimes, proxyTimes, { points = 10, seed = 20261019 } = {}) {
  if (!originalTimes.length || !proxyTimes.length) return { maxMs: Infinity, points: [], byIndex: false, originalFrames: originalTimes.length, proxyFrames: proxyTimes.length };
  const rand = mulberry32(seed);
  const byIndex = originalTimes.length === proxyTimes.length;
  const cuts = [];
  for (let i = 0; i < points; i++) {
    const idx = Math.floor(rand() * originalTimes.length);
    const o = originalTimes[idx], p = byIndex ? proxyTimes[idx] : nearest(proxyTimes, o);
    cuts.push({ at: Number(o.toFixed(3)), gap_ms: Number((Math.abs(p - o) * 1000).toFixed(3)) });
  }
  return { maxMs: Math.max(...cuts.map((c) => c.gap_ms)), points: cuts, byIndex, originalFrames: originalTimes.length, proxyFrames: proxyTimes.length };
}

/** Files a hostile uploader would send dressed as video: playlists that make FFmpeg read local files or call out. */
export function hostilePayloads({ calloutUrl }) {
  return [
    { label: "hls-local-file", name: "evil-hls.mp4", bytes: Buffer.from("#EXTM3U\n#EXT-X-VERSION:3\n#EXT-X-MEDIA-SEQUENCE:0\n#EXTINF:10.0,\nfile:///etc/hostname\n#EXT-X-ENDLIST\n") },
    { label: "concat-local-file", name: "evil-concat.mov", bytes: Buffer.from("ffconcat version 1.0\nfile '/etc/hostname'\n") },
    { label: "hls-callout", name: "evil-callout.mp4", bytes: Buffer.from(`#EXTM3U\n#EXT-X-VERSION:3\n#EXTINF:10.0,\n${calloutUrl}\n#EXT-X-ENDLIST\n`) },
  ];
}
